import{_ as a,o as s,c as o,a2 as t}from"./chunks/framework.BvlN9b-o.js";const m=JSON.parse('{"title":"跟做：移除知识库示例，接入你自己的业务","description":"","frontmatter":{},"headers":[],"relativePath":"tutorials/example-removal.md","filePath":"tutorials/example-removal.md"}'),d={name:"tutorials/example-removal.md"};function r(i,e,c,n,l,p){return s(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="跟做-移除知识库示例-接入你自己的业务" tabindex="-1">跟做：移除知识库示例，接入你自己的业务 <a class="header-anchor" href="#跟做-移除知识库示例-接入你自己的业务" aria-label="Permalink to &quot;跟做：移除知识库示例，接入你自己的业务&quot;">​</a></h1><p>本章回答“这个模板怎么变成我的产品”。知识库示例的存在是为了教你：文档、附件、导出这些真实业务展示了 Core 的每个能力如何被使用。当你开始写自己的业务时，示例应该被<strong>真正删掉</strong>——不是隐藏菜单，而是源码、路由、迁移、任务、教程导航一起消失，而 Core（注册/登录、成员、文件服务、任务、通知、API Key、审计、邮件、限流、遥测）原样保留并继续可验证。这由<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/18710ff9b5ab0827c0d588a325b17dc23788f3a7/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">所有权清单</a>驱动：示例拥有什么、在哪些组装点注册，全部显式登记；<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/18710ff9b5ab0827c0d588a325b17dc23788f3a7/scripts/example-remove.mjs" target="_blank" rel="noreferrer">移除工具</a>按清单操作，不靠文件名关键词猜。</p><h2 id="_1-所有权清单-示例到底拥有什么" tabindex="-1">1. 所有权清单：示例到底拥有什么 <a class="header-anchor" href="#_1-所有权清单-示例到底拥有什么" aria-label="Permalink to &quot;1. 所有权清单：示例到底拥有什么&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/18710ff9b5ab0827c0d588a325b17dc23788f3a7/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">manifest.json</a> 登记五类信息，每类都有检查器钉住：</p><table tabindex="0"><thead><tr><th>登记项</th><th>内容</th><th>谁在检查</th></tr></thead><tbody><tr><td><code>ownedPaths</code></td><td>示例整删的后端模块、Views、迁移、测试、E2E、教程页与研究文档（本示例没有种子数据；若有，同样登记为 ownedPath）</td><td><code>pnpm boundaries:check</code>、清单测试</td></tr><tr><td><code>registrationMarkers</code></td><td>组装点文件里的 <code>example:knowledge:*:start/end</code> 注册区块</td><td>同上，成对且有序才通过</td></tr><tr><td><code>compositionPoints</code></td><td>API/Worker/Web/文档导航等需要改动（而非删除）的文件</td><td>存在性检查</td></tr><tr><td><code>ownedDependencies</code></td><td>只有示例在用的 npm 依赖（如 react-markdown）</td><td>移除时从对应 package.json 剥离</td></tr><tr><td><code>ownedCargoDependencies</code></td><td>只有示例在用的 Rust 依赖（zip、pulldown-cmark）</td><td>移除时从对应 Cargo.toml 剥离</td></tr></tbody></table><p>反向约束同样成文：Core 模块（含后加入的邮件与 telemetry）<strong>不 import Knowledge</strong>——<code>boundaries:check</code> 逐文件扫描 import 方向、SQL 字符串里的表归属与跨模块 Views 引用，注册一个人的“个人库初始化”这类把示例写进 Identity 的捷径，会在检查器处直接失败。每个模块的 <code>module.json</code> 声明自己的表（如 <code>knowledge.documents</code>），迁移里出现的每张表都必须有主人。</p><h2 id="_2-dry-run-先看清楚会发生什么" tabindex="-1">2. dry-run：先看清楚会发生什么 <a class="header-anchor" href="#_2-dry-run-先看清楚会发生什么" aria-label="Permalink to &quot;2. dry-run：先看清楚会发生什么&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-remove</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/18710ff9b5ab0827c0d588a325b17dc23788f3a7/scripts/example-remove.mjs" target="_blank" rel="noreferrer">移除工具</a>列出将要删除的每一条路径、将移除的每个标记区块、导航里将消失的教程页、将剥离的依赖，以及之后要重跑的再生命令——<strong>不写任何文件</strong>。同时它运行保护检查并如实报告：“这份副本现在应用会被拒绝，因为存在未提交改动”。</p><p>保护是硬性的：工具只面向干净的 git 工作副本工作。检测到未提交改动，它会列出脏文件并拒绝执行、一个字节都不动；某个登记标记区块被用户改得不再成对（start/end 各恰好一次），同样拒绝并列出位置。被拒绝时你得到的是清单，不是覆盖——你需要先提交或丢弃自己的改动，或手工解开与示例纠缠的定制。</p><h2 id="_3-移除与两条迁移路径" tabindex="-1">3. 移除与两条迁移路径 <a class="header-anchor" href="#_3-移除与两条迁移路径" aria-label="Permalink to &quot;3. 移除与两条迁移路径&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-remove</span></span></code></pre></div><p>工具按清单精确执行：删除示例拥有的路径，移除组装点里的标记区块（<code>apps/api/src/lib.rs</code> 的路由与 OpenAPI 注册、<code>apps/worker/src/main.rs</code> 的任务注册、Web 路由与视图导出、README、快速开始、<code>.env.example</code>、E2E 环境策略），从 <code>docs/site.json</code> 摘掉示例教程页，剥离示例独占依赖，把清单置为 <code>status: removed</code>（清单本身保留——desktop-smoke 等脚本按它自适应），最后原地重新生成派生产物：<code>pnpm install</code>、<code>cargo update --workspace</code>、<code>pnpm generate</code>（OpenAPI/contracts/SDK）、项目文档引用。结束后用 Core 门禁验收：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-core</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # fmt、clippy、后端测试、contracts 漂移、边界检查</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs-build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 文档站构建，死链会在这里暴露</span></span></code></pre></div><p>迁移历史有两条路径，工具默认走<strong>保守</strong>的那条：</p><ul><li><strong>已运行过或发布过迁移的项目</strong>：什么都不做。<code>0003</code>、<code>0007</code>、<code>0009</code>、<code>0012</code>（示例拥有的迁移）原样保留，<code>_sqlx_migrations</code> 历史完整——源码移除绝不等于删除已有业务数据，这些迁移描述的表留在数据库里，直到你用<strong>新增迁移</strong>显式处理它们。保留路径同时把这四个文件登记进清单的 <code>retainedMigrations</code>：它们的表已经没有代码主人，表归属检查器据此豁免这几个历史文件，而“每张表必须有主人”的规则对其余一切照旧生效。</li><li><strong>全新项目（还没有任何数据库）</strong>：<code>just example-remove --trim-migrations</code> 裁掉示例迁移，新空库从 Core 迁移直接初始化。裁剪只对“从未应用过这些迁移”的副本合法；CI 的删例验收走的就是这条路径，在一个真正的空库上验证。</li></ul><h2 id="_4-移除后-core-还剩什么、什么退场" tabindex="-1">4. 移除后 Core 还剩什么、什么退场 <a class="header-anchor" href="#_4-移除后-core-还剩什么、什么退场" aria-label="Permalink to &quot;4. 移除后 Core 还剩什么、什么退场&quot;">​</a></h2><p>注册/登录与会话、企业成员、文件服务与对象清理、任务与恢复、通知、API Key、审计、密码重置邮件、限流、遥测——全部保留，且有测试钉着：删例后的 <code>just check-core</code> 跑的就是这些幸存测试（<code>registration</code>、<code>members</code>、<code>jobs</code>、<code>config</code>、<code>migration</code>）。邮件与 telemetry 模块不在任何 <code>ownedPath</code> 中，这是手递说明里点名的验收点。</p><p>示例教学的一些能力章节随示例退场（附件、导出、API Key 演示、缓存演示、可观测性演示都以知识库文档为载体）；能力本身和它们的测试留在 Core。生产工具分层清楚：<code>production-backup</code> 与 <code>production-restore</code> 与业务无关（它们只认数据库与对象清单），删例后照常可用；<code>production-smoke</code> 与 <code>production-restore-drill</code> 的种子旅程以示例数据为载体，删例后它们会诚实说明并退出，提示你按同样的骨架为自己的业务写演练——备份数据平面没有变，变的只是旅程。</p><p>性能预算按同一条线分层：注册预算（<code>perf_registration.rs</code>）属于 Core，删例后继续被后端测试钉住；文档列表、创建与导出的预算（<code>perf_documents.rs</code>）和查询计划脚本里的示例列表 SQL 以示例为载体退场——<code>just perf</code> 里的测试选择要换成你自己业务的性能测试，<code>just perf-ci</code> 里的查询计划脚本会诚实说明并退出。</p><p>CI 在每个 PR 上做真实演练：把模板克隆到临时副本，制造脏文件验证保护拒绝，实际执行 <code>--trim-migrations</code> 移除，跑 <code>check-core</code> 与 <code>docs-build</code>，再执行下一节的接入练习。</p><h2 id="_5-接入你自己的业务" tabindex="-1">5. 接入你自己的业务 <a class="header-anchor" href="#_5-接入你自己的业务" aria-label="Permalink to &quot;5. 接入你自己的业务&quot;">​</a></h2><p>删除示例只是开始，教程的承诺是“新业务沿同一套公开接口接入”。CI 里的接入练习由<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/18710ff9b5ab0827c0d588a325b17dc23788f3a7/scripts/example-new-business.mjs" target="_blank" rel="noreferrer">示例脚本</a>执行，你手工操作时沿完全相同的步骤：</p><ol><li><strong>自己的模型与迁移</strong>：新建 <code>migrations/00XX_notes.sql</code>，<code>CREATE SCHEMA notes</code> 建自己的表，<code>module.json</code> 登记表归属（<code>boundaries:check</code> 要求每张表有主人；引用 <code>saas_core.users(id)</code> 这类 Core 稳定标识是允许的跨模块引用）。</li><li><strong>实现模块</strong>：在 <code>crates/app/src/modules/mod.rs</code> 声明 <code>pub mod notes;</code>，在 <code>crates/app/src/modules/notes/</code> 里写 HTTP handler（用 <code>identity::require_session</code> 取当前用户）与领域查询；模块不碰其他模块的私有表。标识符保持字符串、在 SQL 边界显式转换（<code>$1::uuid</code>、<code>RETURNING id::text</code>）——workspace 的 sqlx 不开 uuid 编解码 feature。</li><li><strong>注册路由与 OpenAPI</strong>：在 <code>apps/api/src/lib.rs</code> 的组装点把 <code>notes::router</code> 并入 <code>domain_routes</code>、把 <code>notes::openapi()</code> 并入文档。</li><li><strong>生成 SDK</strong>：<code>pnpm generate</code> 让 contracts/SDK 出现你的资源类型。</li><li><strong>测试</strong>：像 <code>apps/api/tests/notes.rs</code> 那样在公开 HTTP 接口上断言注册 → 创建 → 读取（<code>#[sqlx::test]</code> 需要一个 PostgreSQL，<code>just test-backend</code> 会自备一次性实例）。</li></ol><p>练习脚本替你把这些文件写进临时副本，借助<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/18710ff9b5ab0827c0d588a325b17dc23788f3a7/scripts/lib/postgres.mjs" target="_blank" rel="noreferrer">同一条测试postgres通道</a>跑 <code>cargo test</code> 与 clippy——CI 绿灯就是“删例后接入路径可用”的可执行证据。</p><h2 id="_6-运行本章检查" tabindex="-1">6. 运行本章检查 <a class="header-anchor" href="#_6-运行本章检查" aria-label="Permalink to &quot;6. 运行本章检查&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/example-remove.test.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example-remove</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>清单与工作副本之间的漂移由两层钉住：<code>boundaries:check</code> 在每次 <code>just check</code> 里验证登记路径与标记区块，<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/18710ff9b5ab0827c0d588a325b17dc23788f3a7/tests/tooling/example-remove.test.mjs" target="_blank" rel="noreferrer">清单工具测试</a>在合成副本上验证移除语义本身——dry-run 零写入、精确删除与标记编辑、导航裁剪、依赖剥离、迁移默认保留与 <code>--trim-migrations</code>、脏副本与结构破坏的拒绝。真正的删例验收在 CI 的 <code>example-removal</code> job 里对全新副本完整执行。</p><hr><p>源码版本：<code>18710ff9b5ab</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/18710ff9b5ab0827c0d588a325b17dc23788f3a7/docs/tutorials/23-example-removal.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,30)])])}const b=a(d,[["render",r]]);export{m as __pageData,b as default};
